// Original Kō explanations and sentences; source indexes supply reference identities only.
const p=(id,purpose,formation,register,restrictions,mistake,examples)=>({id,purpose,formation:[formation],register,restrictions,mistake,examples:examples.map(([text,translation,note,readings])=>({text,translation,note,...(readings?{readings}:{})}))});
export default [
p('n4-001','Describe an action continuing throughout another period.','Plain nonpast verb / ている + 間; noun + の間.','Neutral','The main state or action lasts across the relevant interval.','Use 間に when locating a bounded event somewhere within the interval.',[
 ['母が料理している[間]、私は皿を洗った。','While my mother was cooking, I washed dishes.','Parallel activities.',{'間':'あいだ'}],['夏休みの[間]、祖母の家にいた。','I stayed at my grandmother’s throughout summer vacation.','A continuing stay.',{'間':'あいだ'}],['電車を待つ[間]、本を読んでいた。','I was reading while waiting for the train.','An activity fills the wait.',{'間':'あいだ'}]]),
p('n4-002','Locate an event within an available time window.','Plain nonpast verb / ている + 間に; noun + の間に.','Neutral','The main event occurs within the interval rather than necessarily lasting throughout it.','Do not assume 間に means the two actions continue for the same duration.',[
 ['母が出かけている[間に]、掃除をした。','I cleaned while my mother was out.','Complete something within the window.',{'間に':'あいだに'}],['休み時間の[間に]、先生に質問した。','I asked the teacher a question during the break.','A bounded event.',{'間に':'あいだに'}],['電車を待つ[間に]、メールを一通送った。','I sent an email while waiting for the train.','Use a short opportunity.',{'間に':'あいだに'}]]),
p('n4-003','Downplay how much or how often something happens.','あまり + negative predicate.','Neutral','The ordinary meaning is not very much, rather than an absolute zero.','Use a negative predicate for this basic pattern.',[
 ['朝は[あまり]食べ[ない]。','I do not eat much in the morning.','A small amount.'],['この町は[あまり]寒く[ない]です。','This town is not very cold.','A moderate property.'],['最近は[あまり]映画を見[ない]。','I do not watch films much these days.','Low frequency.']]),
p('n4-004','Place an action after a completed event.','た-form + 後で; noun + の後で.','Neutral','The first event is treated as completed before the main event.','Use 食べた後で, not 食べる後で.',[
 ['昼ご飯を食べた[後で]、散歩します。','I will take a walk after lunch.','A completed preceding action.'],['会議の[後で]、少し話しましょう。','Let us talk briefly after the meeting.','A noun names the event.'],['宿題が終わった[後で]、ゲームをした。','I played a game after finishing my homework.','Past sequence.']]),
p('n4-005','Make a result depend on a condition.','Verb conditional ～ば; い-adjective ～ければ; noun / な-adjective + なら（ば）.','Neutral','Volitional requests can be restricted when the condition is a controllable action by the same person.','Choose the conditional that fits the situation rather than freely swapping all forms.',[
 ['時間があれ[ば]、手伝います。','If I have time, I will help.','A state enables an action.'],['安けれ[ば]、買いたいです。','If it is inexpensive, I would like to buy it.','A price condition.'],['このボタンを押せ[ば]、画面が変わります。','If you press this button, the screen changes.','A repeatable result.']]),
p('n4-006','Introduce the circumstances under which instructions apply.','Plain clause + 場合は; noun + の場合は; な-adjective + な場合は.','Neutral / formal','Often used for contingency instructions or rules.','Use の after a noun before 場合.',[
 ['雨の[場合は]、体育館に集まってください。','If it rains, please gather in the gym.','An alternative arrangement.'],['遅れる[場合は]、電話してください。','If you will be late, please call.','A contingency.'],['都合が悪い[場合は]、別の日にしましょう。','If it is inconvenient, let us choose another day.','An accommodating condition.']]),
p('n4-007','Emphasize concentration on one thing or repeated activity.','Noun + ばかり; て-form + ばかりいる.','Neutral','Often suggests an imbalance; たばかり and approximate quantity ばかり are separate uses.','Do not treat every ばかり as just-finished time.',[
 ['弟はお菓子[ばかり]食べている。','My younger brother eats nothing but sweets.','An unbalanced choice.'],['休みの日は寝て[ばかり]いる。','On days off, I do little but sleep.','Repeated activity.'],['この店は若い人[ばかり]だ。','This shop is full of young people.','A concentrated group.']]),
p('n4-008','Show that a limited action or resource is sufficient.','Noun / dictionary-form verb + だけで.','Neutral','The following result explains what that limited input achieves.','Distinguish sufficiency from merely restricting a list.',[
 ['名前を書く[だけで]、登録できます。','You can register just by writing your name.','A minimal requirement.'],['声を聞く[だけで]、安心します。','Just hearing your voice reassures me.','A small input produces a feeling.'],['この切符[だけで]、入れます。','You can enter with just this ticket.','A sufficient item.']]),
p('n4-009','Describe an action suddenly starting or something moving out.','ます-stem + 出す.','Neutral','Often highlights onset; lexical compounds may have an outward-direction meaning.','出す follows a stem, not a full ます form.',[
 ['赤ちゃんが泣き[出した]。','The baby started crying.','A sudden onset.'],['急に雨が降り[出した]。','It suddenly started raining.','A change in weather.'],['箱から本を取り[出した]。','I took a book out of the box.','An outward compound.']]),
p('n4-010','Identify something with a very polite copula.','Noun / な-adjective + でございます.','Very polite','It raises the politeness of the statement rather than honoring the subject by itself.','It does not attach directly after an い-adjective in the same way.',[
 ['こちらが会議室[でございます]。','This is the meeting room.','Customer-facing guidance.'],['私は受付の田中[でございます]。','I am Tanaka from reception.','A formal introduction.'],['料金は千円[でございます]。','The charge is one thousand yen.','A polite service statement.']]),
p('n4-011','Offer one example as a relaxed suggestion.','Noun + でも + suggestion or choice.','Conversational','It presents a possible example rather than limiting the choice to that item.','This noun-attached use differs from sentence-initial but.',[
 ['お茶[でも]飲みませんか。','Would you like some tea or something?','A relaxed invitation.'],['週末は映画[でも]見よう。','Let us watch a film or something this weekend.','One possible activity.'],['少し公園[でも]歩きましょう。','Let us take a short walk in the park or somewhere.','A gentle suggestion.']]),
p('n4-012','Seek agreement or frame an emphatic discovery.','Plain clause + ではないか; nouns generally omit predicate だ.','Formal / rhetorical','Can sound assertive or argumentative; polite intonation does not make every context gentle.','This rhetorical pattern often affirms the proposition rather than denying it.',[
 ['これは良い案[ではないか]。','Is this not a good plan?','Invite agreement.'],['もう電車が来ている[ではないか]。','The train is already here, look.','An emphatic discovery.'],['もう少し考える必要があるの[ではないか]。','Do we not need to think about it a little more?','A rhetorical proposal.']]),
p('n4-013','State that a resource or quality is necessary.','Noun + が必要.','Neutral','The noun names what is needed; 必要がある follows an action.','Use a nominalized form when naming an action as the necessary thing.',[
 ['この仕事には経験[が必要]です。','Experience is necessary for this job.','A required quality.'],['入場には予約[が必要]です。','A reservation is required for entry.','A service requirement.'],['もう少し時間[が必要]です。','I need a little more time.','A needed resource.']]),
p('n4-014','Describe a sensory impression that is perceived.','Sound / smell / taste noun + がする.','Neutral','Use an appropriate sensory noun; this is not a general replacement for sensing every state.','音がする describes hearing a sound, not deliberately making it.',[
 ['台所からいい匂い[がします]。','A lovely smell is coming from the kitchen.','Smell.'],['外で変な音[がした]。','There was a strange sound outside.','Sound.'],['このお茶は甘い味[がする]。','This tea tastes sweet.','Taste.']]),
p('n4-015','Name a person with a noticeable sensitivity or tendency.','Certain adjective stems + がり.','Conversational','Only established combinations are natural; it is not freely productive with every adjective.','Distinguish the person noun 寒がり from the verb 寒がる.',[
 ['弟は寒[がり]です。','My younger brother is sensitive to the cold.','A sensitivity.'],['姉は怖[がり]で、暗い所が苦手です。','My older sister is easily frightened and dislikes dark places.','A tendency.'],['友達は恥ずかし[がり]です。','My friend is shy.','An established personality description.']]),
p('n4-016','Describe outward signs of another person’s feelings.','Adjective stem + がる; ongoing signs + がっている.','Neutral','Usually reports observed behavior rather than claiming direct access to someone’s feelings.','Use 欲しがる for observed wanting; speaker desire normally uses 欲しい.',[
 ['子供が暗い部屋を怖[がっている]。','The child is showing fear of the dark room.','Observable reaction.'],['弟は新しい靴を欲し[がっている]。','My younger brother wants new shoes.','Observed or reported desire.'],['犬が外へ出た[がっている]。','The dog wants to go outside.','Visible desire to act.']]),
p('n4-017','State availability or existence very politely.','Inanimate noun + がございます.','Very polite','Use respectful いらっしゃる for a person’s presence, not ございます.','It is the polite counterpart of ある rather than いる.',[
 ['こちらに空席[がございます]。','There is a seat available here.','Service availability.'],['何かご質問[がございます]か。','Do you have any questions?','A very polite inquiry.'],['入口に案内板[がございます]。','There is an information board at the entrance.','Guide a visitor.']]),
p('n4-018','Describe the beginning of an activity or process.','ます-stem + 始める.','Neutral','The compound can describe deliberate or natural onset; context supplies the actor’s control.','Attach to the stem rather than the dictionary form.',[
 ['去年、日本語を習い[始めた]。','I started learning Japanese last year.','An intentional beginning.'],['花が咲き[始めました]。','The flowers have begun to bloom.','A natural process.'],['先生が話し[始める]と、皆が静かになった。','When the teacher began speaking, everyone became quiet.','Onset of an action.']]),
p('n4-019','State an expectation supported by what you know.','Plain clause + はずだ; noun + のはず; な-adjective + なはず.','Neutral','The expectation may turn out wrong; it is not an obligation.','Use の after a noun before はず.',[
 ['田中さんはもう駅にいる[はずです]。','Ms. Tanaka should be at the station already.','An expectation based on a schedule.'],['この店は今日は休みの[はずだ]。','This shop should be closed today.','Known opening information.'],['鍵は鞄に入れた[はずです]。','I am sure I put the key in my bag.','An expectation from memory.']]),
p('n4-020','Reject a possibility as inconsistent with your knowledge.','Plain clause + はずがない; noun + のはずがない.','Neutral','A strong personal judgment, rather than independent proof of impossibility.','It means cannot reasonably be so, not must not do it.',[
 ['あの人が約束を忘れる[はずがない]。','There is no way that person would forget a promise.','Confidence in a person.'],['こんなに早く終わる[はずがない]。','It cannot possibly finish this quickly.','An expected time requirement.'],['今日は日曜日だから、学校がある[はずがない]。','It is Sunday, so there cannot be school today.','Reason-based rejection.']]),
p('n4-021','State that performing an action is necessary.','Dictionary-form verb + 必要がある.','Neutral / formal','The expression evaluates a practical need; it is not inherently an order.','Keep the action in dictionary form before 必要.',[
 ['住所を確認する[必要があります]。','We need to confirm the address.','A practical requirement.'],['もう一度話し合う[必要がある]。','We need to discuss it again.','A necessary next step.'],['予約をする[必要はありません]。','There is no need to make a reservation.','Negating the necessity.']]),
p('n4-022','Express intention or suggest a shared action in plain speech.','Ichidan ～よう; godan final u-sound → o-sound + う; する → しよう; 来る → 来よう.','Plain','It may express a personal decision or invitation depending on context.','Do not form godan volitionals by simply adding よう.',[
 ['今日は早く寝[よう]。','I will go to bed early today.','A personal decision.'],['一緒に帰[ろう]。','Let us go home together.','A casual invitation.'],['明日、もう一度話[そう]。','Let us talk again tomorrow.','A proposed action.']]),
p('n4-023','Refer respectfully to someone’s presence or movement.','いらっしゃる replaces いる, 行く, or 来る.','Respectful','Use for someone being honored, rather than your own action.','The same verb has three meanings; context identifies presence, arrival, or departure.',[
 ['先生は研究室に[いらっしゃいます]。','The teacher is in the office.','Respectful presence.'],['明日は何時に[いらっしゃいます]か。','What time will you come tomorrow?','Respectful arrival.',{"何時":"なんじ"}],['社長は来週、大阪へ[いらっしゃいます]。','The company president is going to Osaka next week.','Respectful movement.']]),
p('n4-024','Describe your own action humbly and politely.','いたす / いたします replaces する.','Humble / polite','Typically lowers the speaker’s or in-group action in a respectful interaction.','Do not use it as a respectful verb for the customer’s action.',[
 ['私からご連絡[いたします]。','I will contact you.','A humble commitment.'],['資料をお送り[いたします]。','I will send the documents.','A service action.'],['明日、確認[いたします]。','I will check tomorrow.','A polite promise.']]),
p('n4-025','Seek agreement or point out something emphatically in casual speech.','Plain clause + じゃないか.','Casual / emphatic','It can sound confrontational depending on intonation.','A rhetorical じゃないか need not negate the proposition.',[
 ['この案はいい[じゃないか]。','This plan is good, is it not?','An approving reaction.'],['もう九時[じゃないか]。','It is already nine.','An emphatic realization.',{"九時":"くじ"}],['前にも言った[じゃないか]。','I told you before, did I not?','A forceful reminder.']]),
p('n4-026','Embed a yes-or-no uncertainty inside a sentence.','Plain clause + かどうか; nouns and な-adjectives omit だ.','Neutral','The surrounding predicate often concerns knowing, checking, or deciding.','Use a question word + か without どうか for ordinary embedded who/where questions.',[
 ['明日行ける[かどうか]、まだ分かりません。','I do not yet know whether I can go tomorrow.','Uncertain attendance.'],['店が開いている[かどうか]確認します。','I will check whether the shop is open.','A verification task.',{"開い":"あい"}],['これが本物[かどうか]調べてください。','Please check whether this is genuine.','A noun predicate without だ.']]),
p('n4-027','Wonder aloud using a soft sentence ending.','Plain clause + かしら.','Conversational; traditionally feminine-associated','Choice depends on speaker style and social context, not grammatical gender agreement.','Avoid treating it as a universally neutral formal question ending.',[
 ['明日は晴れる[かしら]。','I wonder whether it will be sunny tomorrow.','A personal wondering.'],['鍵はどこに置いた[かしら]。','I wonder where I put the key.','Search your memory.'],['この服で大丈夫[かしら]。','I wonder whether these clothes will be all right.','Uncertainty about suitability.']]),
p('n4-028','Ask a familiar yes-or-no question.','Plain clause + かい.','Familiar; often older or masculine-associated speech','Can sound patronizing outside a close relationship.','It usually suits yes/no questions better than ordinary question-word questions.',[
 ['もうご飯を食べた[かい]。','Have you eaten yet?','A familiar inquiry.'],['明日は暇[かい]。','Are you free tomorrow?','A casual question.'],['この本を借りてもいい[かい]。','May I borrow this book?','Ask someone familiar.']]),
p('n4-029','Leave a possibility open without asserting it.','Plain clause + かもしれない; nouns and な-adjectives omit だ.','Neutral','It indicates uncertainty rather than a fixed numerical probability.','Use 学生かもしれない, not 学生だかもしれない.',[
 ['午後は雨が降る[かもしれません]。','It may rain this afternoon.','A possible event.'],['鍵を会社に忘れた[かもしれない]。','I may have left my key at work.','Uncertain memory.'],['あの人は新しい先生[かもしれません]。','That person might be the new teacher.','A tentative identification.']]),
p('n4-030','Express an informal wondering or uncertainty.','Plain clause + かな.','Casual','Often self-directed; use a more explicit polite question when addressing strangers.','Nouns do not take plain だ immediately before かな.',[
 ['明日は雨[かな]。','I wonder whether it will rain tomorrow.','An informal prediction.'],['この道で合っている[かな]。','I wonder whether this is the right road.','Check a possibility.'],['何を作ろう[かな]。','I wonder what I should make.','Consider a choice.']]),
p('n4-031','Name the material from which something is made.','Material noun + から作る / から作られる.','Neutral','Often used when the source material is transformed and not visually obvious.','Do not assume から and material で are interchangeable in every context.',[
 ['この酒は米[から作られています]。','This sake is made from rice.','A transformed ingredient.'],['チーズは牛乳[から作られます]。','Cheese is made from milk.','An ingredient becomes a new product.'],['古い紙[から]新しい紙を[作ります]。','We make new paper from old paper.','A recycling process.']]),
p('n4-032','Express a confident expectation or reassurance.','きっと + expected predicate.','Neutral','It reflects confidence; it does not guarantee factual certainty.','Do not treat きっと as independent evidence.',[
 ['明日は[きっと]晴れます。','It will surely be sunny tomorrow.','A confident prediction.'],['友達は[きっと]喜ぶでしょう。','My friend will surely be pleased.','An expected reaction.'],['練習すれば、[きっと]上手になります。','If you practice, you will surely improve.','Encouragement.']]),
p('n4-033','Locate something at an approximate time or life stage.','Clock time + ごろ; clause / noun + ころ.','Neutral','Clock times typically take ごろ; broader periods often take ころ.','Use an approximation rather than interpreting it as an exact appointment time.',[
 ['七時[ごろ]帰ります。','I will return around seven.','An approximate time.',{"七時":"しちじ"}],['子供の[ころ]、ここに住んでいました。','I lived here when I was a child.','A life period.'],['桜が咲く[ころ]、また来ます。','I will come again when the cherry blossoms bloom.','A seasonal period.']]),
p('n4-034','Treat an action or fact as a noun-like idea.','Plain clause + こと.','Neutral','Some expressions prefer こと and others の; they are not freely interchangeable everywhere.','Keep the nominalized action’s internal grammar intact.',[
 ['毎日歩く[こと]は大切です。','Walking every day is important.','An action as topic.'],['外国語を学ぶ[こと]が好きです。','I like learning foreign languages.','An activity as an object of preference.'],['約束を守る[こと]を忘れないでください。','Please do not forget to keep your promise.','A matter to remember.']]),
p('n4-035','Say that something occasionally happens.','Dictionary-form / ない-form verb + ことがある.','Neutral','The nonpast action describes occasional occurrence; たことがある concerns experience.','Do not translate every ことがある as have ever.',[
 ['週末は会社へ行く[ことがあります]。','I sometimes go to work on weekends.','An occasional action.'],['忙しくて昼ご飯を食べない[ことがある]。','Sometimes I am too busy to eat lunch.','Occasional non-occurrence.'],['この電車は遅れる[ことがあります]。','This train is sometimes late.','An intermittent event.']]),
p('n4-036','Express an ability or available possibility.','Dictionary-form verb + ことができる.','Neutral','It can express skill, permission-like availability, or circumstances enabling an action.','The action stays in dictionary form before こと.',[
 ['私は漢字を読む[ことができます]。','I can read kanji.','A skill.'],['ここで切符を買う[ことができます]。','You can buy tickets here.','An available service.'],['今日は早く帰る[ことができた]。','I was able to leave early today.','Circumstances allowed an action.']]),
p('n4-037','Report a decision or arrangement as established.','Dictionary-form / ない-form verb + ことになる.','Neutral','The expression backgrounds who decided; the speaker may still have participated.','It does not always mean the outcome happened by pure chance.',[
 ['来月、大阪へ転勤する[ことになりました]。','It has been arranged that I will transfer to Osaka next month.','An established work arrangement.'],['会議は金曜日に開く[ことになった]。','It was decided to hold the meeting on Friday.','A shared decision.'],['今年は旅行しない[ことになりました]。','It has been decided that we will not travel this year.','A negative arrangement.']]),
p('n4-038','Present a deliberate decision about an action.','Dictionary-form / ない-form verb + ことにする.','Neutral','Focuses on the decision-maker’s choice; habitual ことにしている describes a personal rule.','Distinguish choosing an action from reporting an externally framed arrangement.',[
 ['毎朝歩く[ことにしました]。','I decided to walk every morning.','A personal decision.'],['今日は出かけない[ことにする]。','I have decided not to go out today.','A negative choice.'],['会議はオンラインで行う[ことにしましょう]。','Let us decide to hold the meeting online.','A group decision.']]),
p('n4-039','Cause a property expressed by an い-adjective to change.','い-adjective → ～く + する.','Neutral','する presents a caused change; なる describes becoming.','Remove final い before adding くする; いい uses よくする.',[
 ['音を小さ[くしてください]。','Please turn the sound down.','Reduce a degree.'],['部屋を明る[くしました]。','I made the room brighter.','Cause a change.'],['説明を短[くします]。','I will make the explanation shorter.','Modify a presentation.']]),
p('n4-040','Describe an abrupt change or unexpected onset.','急に + predicate.','Neutral','It emphasizes suddenness rather than necessarily urgency.','Do not use 急に as the ordinary expression for doing a task quickly.',[
 ['[急に]雨が降り始めた。','It suddenly began to rain.','Unexpected weather.'],['部屋が[急に]暗くなった。','The room suddenly became dark.','An abrupt state change.'],['予定が[急に]変わりました。','The plan changed suddenly.','An unexpected development.']]),
p('n4-041','Set a deadline for completing an action.','Deadline noun / clause + までに.','Neutral','The action happens by the endpoint; it need not continue throughout the interval.','Use まで for an activity continuing until a time.',[
 ['金曜日[までに]返事をください。','Please reply by Friday.','A reply deadline.'],['九時[までに]駅に着きたいです。','I want to reach the station by nine.','An arrival target.',{"九時":"くじ"}],['先生が来る[までに]、準備を終えよう。','Let us finish preparing before the teacher arrives.','An event sets the deadline.']]),
p('n4-042','Keep a state unchanged while something else happens.','た-form / ない-form + まま; noun + のまま; な-adjective + なまま.','Neutral','The retained state must make sense alongside the main action.','ている normally describes a state itself; まま emphasizes leaving it unchanged.',[
 ['靴を履いた[まま]、部屋に入った。','I entered the room with my shoes still on.','A retained result.'],['窓を開けた[まま]寝てしまった。','I fell asleep with the window left open.','An unattended state.'],['何も言わない[まま]帰った。','I went home without saying anything.','A state of non-action continues.']]),
p('n4-043','Present alternatives in a formal list or instruction.','A + または + B.','Neutral / written','Typically offers alternatives rather than including both together.','Use 及び or と for an inclusive list when appropriate.',[
 ['黒[または]青のペンを使ってください。','Please use a black or blue pen.','Either option is acceptable.'],['電話[または]メールでお知らせください。','Please notify us by phone or email.','Alternative contact methods.'],['本人[または]家族が受け取れます。','The person concerned or a family member can receive it.','Alternative recipients.']]),
p('n4-044','Make a conversational comparison or inference.','Plain clause / noun + みたいだ.','Conversational','Can express resemblance or an evidence-based impression; it is less formal than ようだ.','Do not insert だ after a noun immediately before みたい.',[
 ['あの雲は動物[みたいだ]。','That cloud looks like an animal.','Resemblance.'],['隣の部屋に誰かいる[みたいです]。','It seems someone is in the next room.','An inference from signs.'],['今日は休み[みたいです]。','It looks like the place is closed today.','A noun-based inference.']]),
p('n4-045','Modify a noun through a conversational resemblance.','Noun / plain phrase + みたいな + noun.','Conversational','The following noun is what is being described.','Use な before the modified noun, not に.',[
 ['雪[みたいな]白い花です。','It is a white flower like snow.','A visual resemblance.'],['夢[みたいな]一日でした。','It was a dreamlike day.','An impression.'],['先生[みたいな]人になりたいです。','I want to become someone like my teacher.','A model for a person.']]),
p('n4-046','Describe an action or property by resemblance.','Noun / plain phrase + みたいに + predicate.','Conversational','に makes the resemblance modify the following action or description.','Use みたいな when directly modifying a noun.',[
 ['鳥[みたいに]空を飛びたい。','I want to fly through the sky like a bird.','A manner of action.'],['子供[みたいに]笑った。','She laughed like a child.','A comparison of behavior.'],['今日は夏[みたいに]暑い。','It is hot like summer today.','A comparison of degree.']]),
p('n4-047','Emphasize a quantity as surprisingly large.','Quantity expression + も.','Neutral','The surprise comes from the speaker’s expectations rather than a fixed numerical threshold.','This も need not mean another item too.',[
 ['駅まで一時間[も]歩いた。','I walked for a whole hour to the station.','A long duration.'],['会場には百人[も]来た。','As many as a hundred people came to the venue.','A large attendance.'],['この本は三千円[も]する。','This book costs as much as three thousand yen.','An unexpectedly high price.']]),
p('n4-048','Forbid an action using a direct sentence ending.','Dictionary-form verb + な.','Strong / plain','Common in abrupt warnings or commands; usually unsuitable for a polite request.','This な is not the な of a な-adjective or the ending in なさい.',[
 ['ここで走る[な]。','Do not run here.','A direct warning.'],['そのボタンを押す[な]。','Do not press that button.','An urgent prohibition.'],['約束を忘れる[な]よ。','Do not forget your promise.','A forceful reminder.']]),
p('n4-049','Provide illustrative items or soften a reference.','Noun + など.','Neutral','A list with など is non-exhaustive; tone can also minimize an item.','Do not interpret an example list as necessarily complete.',[
 ['机には本やノート[など]があります。','There are things such as books and notebooks on the desk.','Examples of objects.'],['京都や奈良[など]を訪ねました。','I visited places such as Kyoto and Nara.','Representative destinations.'],['果物[など]はいかがですか。','How about some fruit or something similar?','A softened suggestion.']]),
p('n4-050','Perform one action while also doing another.','ます-stem + ながら + main action.','Neutral','The actions ordinarily share a subject; the final action is the main one.','This simultaneous use differs from concessive ながら meaning although.',[
 ['音楽を聞き[ながら]料理します。','I cook while listening to music.','Parallel activities.'],['歩き[ながら]話しましょう。','Let us talk while walking.','A shared moving conversation.'],['地図を見[ながら]道を探した。','I looked for the route while consulting a map.','A supporting action.']]),
p('n4-051','Describe an expected action as difficult to make happen.','なかなか + negative predicate.','Neutral','Often implies that progress is slower or harder than hoped.','Positive なかなか can instead praise something as quite good.',[
 ['バスが[なかなか]来[ない]。','The bus is taking ages to come.','An expected arrival is delayed.'],['この漢字は[なかなか]覚えられ[ない]。','I cannot seem to remember this kanji.','Difficulty despite effort.'],['忙しくて、[なかなか]休め[ない]。','I am so busy that I can hardly take a break.','An action is hard to achieve.']]),
p('n4-052','State that failing to act would be unacceptable.','ない-form → なければ + いけない.','Neutral','Common for practical duties or requirements.','The whole expression obliges the action despite its negative components.',[
 ['明日は早く起き[なければいけない]。','I have to get up early tomorrow.','A practical necessity.'],['この書類を出さ[なければいけません]。','I must submit this document.','A formal requirement.'],['部屋を片付け[なければいけない]。','I have to tidy the room.','A personal task.']]),
p('n4-053','Present an action as a duty or necessity.','ない-form → なければ + ならない.','Neutral / formal','Often suits duties, rules, or serious requirements.','It does not mean that the action must not happen.',[
 ['法律を守ら[なければならない]。','We must obey the law.','A general duty.'],['原因を調べ[なければなりません]。','We must investigate the cause.','A serious task.'],['来週までに決め[なければならない]。','We must decide by next week.','A deadline-based necessity.']]),
p('n4-054','Respond to a proposed situation with relevant advice or judgment.','Plain clause + なら; noun / な-adjective + なら.','Neutral','Often treats the condition as a topic or premise already raised.','The action in the main clause can occur before the conditional event.',[
 ['京都へ行く[なら]、この店がおすすめです。','If you are going to Kyoto, I recommend this shop.','Advice based on a plan.'],['明日が無理[なら]、来週にしましょう。','If tomorrow is impossible, let us do it next week.','Respond to a limitation.'],['車で行く[なら]、先に駐車場を調べよう。','If we are going by car, let us check parking first.','Preparation before the proposed action.']]),
p('n4-055','Give an instruction from a position of authority.','ます-stem + なさい.','Directive','Common from parents or teachers; it is not a generally polite request to a superior.','Use the stem, not dictionary-form verb + なさい.',[
 ['早く寝[なさい]。','Go to bed early.','A parent’s instruction.'],['ここに名前を書き[なさい]。','Write your name here.','A classroom direction.'],['人の話をよく聞き[なさい]。','Listen carefully to other people.','An authoritative reminder.']]),
p('n4-056','Refer respectfully to another person’s action.','なさる replaces する; polite form なさいます.','Respectful','Use for a person being honored, rather than the speaker’s own humble action.','The polite form is なさいます, not なさります.',[
 ['先生は週末、何を[なさいます]か。','What do you do on weekends, Professor?','A respectful question.'],['社長は毎朝、運動を[なさいます]。','The company president exercises every morning.','A respected person’s routine.'],['どう[なさいました]か。','What is the matter?','A conventional polite inquiry.']]),
p('n4-057','Describe becoming aware of something.','Noun + に気がつく; plain clause + のに気がつく.','Neutral','Focuses on the moment of noticing rather than long-standing knowledge.','A clause needs nominalization before に.',[
 ['帰ってから、忘れ物[に気がついた]。','After getting home, I noticed I had left something behind.','A discovery.'],['窓が開いているの[に気がついた]。','I noticed that the window was open.','Notice a state.',{"開い":"あい"}],['小さな間違い[に気がつきました]。','I noticed a small mistake.','An observed detail.']]),
p('n4-058','Describe how someone or something appears visually.','Noun / な-adjective + に見える; い-adjective ～く見える.','Neutral','Reports appearance rather than asserting the underlying reality.','Use 若く見える, not 若いに見える.',[
 ['あの雲は犬[に見える]。','That cloud looks like a dog.','A visual resemblance.'],['この服を着ると、若[く見えます]。','I look younger when I wear these clothes.','An apparent property.'],['この部屋は広[く見える]。','This room looks spacious.','A visual impression.']]),
p('n4-059','Deliberately change a state expressed by a noun or な-adjective.','Noun / な-adjective + にする.','Neutral','The expression presents a caused change; にする can also select an option in other contexts.','い-adjectives form ～くする instead.',[
 ['部屋をきれい[にします]。','I will make the room clean.','An intentional change.'],['会場を静か[にしてください]。','Please make the venue quiet.','Cause a new state.'],['古い部屋を書斎[にしました]。','I turned the old room into a study.','A new use or role.']]),
p('n4-060','Describe an action as difficult to perform.','ます-stem + にくい.','Neutral','Often relates to a property of the object or circumstances; it conjugates as an い-adjective.','Use 読みにくい, not 読むにくい.',[
 ['この字は読み[にくい]。','This writing is hard to read.','A difficult object.'],['この靴は歩き[にくい]です。','These shoes are difficult to walk in.','An inconvenient tool.'],['この瓶は開け[にくかった]。','This bottle was hard to open.','A past difficulty.']]),
p('n4-061','Locate or compare an item within a group.','Group noun + の中で.','Neutral','The group supplies the range of the comparison.','Distinguish a group comparison from the literal inside of a container.',[
 ['三人[の中で]、誰が一番早いですか。','Who is the fastest of the three?','A comparison set.'],['季節[の中で]、秋が一番好きです。','Of all the seasons, I like autumn best.','A preferred member.'],['この一覧[の中で]、使える案を選びましょう。','Let us choose a usable plan from this list.','Selection within a group.']]),
p('n4-062','Present a result that runs against an expectation.','Plain clause + のに; noun / な-adjective + なのに.','Neutral','Often conveys surprise, regret, or dissatisfaction.','This concessive のに differs from purpose or use のに.',[
 ['薬を飲んだ[のに]、まだ痛い。','I took medicine, but it still hurts.','An expected improvement fails.'],['日曜日[なのに]、会社へ行きます。','Even though it is Sunday, I am going to work.','A contrast with expectations.'],['近い[のに]、一度も行ったことがない。','Although it is nearby, I have never been there.','An unexpected absence of experience.',{"行っ":"いっ"}]]),
p('n4-063','Mark the purpose or task for which something is useful or required.','Dictionary-form verb + のに + useful / necessary / time-cost expression.','Neutral','The following predicate evaluates what is needed or useful for the activity.','This use does not mean although.',[
 ['この道具は野菜を切る[のに]便利です。','This tool is useful for cutting vegetables.','Usefulness for a task.'],['駅まで行く[のに]三十分かかります。','It takes thirty minutes to get to the station.','Time required for an activity.',{"三十分":"さんじゅっぷん"}],['申し込む[のに]写真が必要です。','A photograph is needed to apply.','An application requirement.']]),
p('n4-064','Focus on the identity or explanation of a particular part.','Plain clause + のは + focused element + だ.','Neutral','The nominalized clause sets up what is being identified.','Keep the question or focus relation clear; のは does not simply mean because.',[
 ['この絵を描いた[のは]姉[です]。','The person who painted this picture is my older sister.','Identify the artist.'],['私が欲しい[のは]この本[です]。','What I want is this book.','Focus on the desired object.'],['出発する[のは]明日[です]。','It is tomorrow that we leave.','Focus on the time.']]),
p('n4-065','Ask respectfully for an action using an honorific pattern.','お + ます-stem + ください; certain ご + action nouns + ください.','Respectful request','Established usage matters; some verbs prefer their own honorific forms.','Do not add お to the full dictionary form.',[
 ['少々[お]待ち[ください]。','Please wait a moment.','A service request.'],['こちらを[お]読み[ください]。','Please read this.','A respectful instruction.'],['どうぞ[お]入り[ください]。','Please come in.','Invite entry.']]),
p('n4-066','Describe another person’s action respectfully.','お + ます-stem + になる; some verbs have special honorific forms.','Respectful','Use for the honored person’s action rather than your own.','Use the stem between お and になる.',[
 ['先生はもう[お]帰り[になりました]。','The teacher has already gone home.','Respectful departure.'],['社長が資料を[お]読み[になっています]。','The company president is reading the documents.','A respected person’s action.'],['こちらの椅子を[お]使い[になります]か。','Will you use this chair?','A respectful question.']]),
p('n4-067','Mark regular spacing between repeated events.','Quantity of time / distance + おきに.','Neutral','Day-based expressions can be interpreted differently in casual use; clarify dates when precision matters.','Distinguish a gap between events from a count of events.',[
 ['このバスは十分[おきに]来ます。','This bus comes every ten minutes.','A regular interval.',{"十分":"じゅっぷん"}],['道には百メートル[おきに]標識がある。','There is a sign every hundred meters along the road.','Repeated spacing.'],['三十分[おきに]少し休みます。','I take a short break every thirty minutes.','A work interval.',{"三十分":"さんじゅっぷん","十分":"じゅっぷん"}]]),
p('n4-068','Describe completing an action.','ます-stem + 終わる.','Neutral','The action needs a meaningful endpoint; some verbs combine more naturally than others.','終わる follows the verb stem.',[
 ['この本を読み[終わりました]。','I finished reading this book.','Completion of reading.'],['夕食を食べ[終わった]ら、出かけよう。','Let us go out after finishing dinner.','Completion before another action.'],['名前を書き[終わった]人は出してください。','Those who have finished writing their names should hand it in.','A completed task.']]),
p('n4-069','Express ability using the potential form.','Ichidan stem + られる; 来る → 来られる.','Neutral','られる also forms passive and honorific expressions; context determines the use.','Avoid assuming every られる expresses ability.',[
 ['私は生の魚を食べ[られます]。','I can eat raw fish.','A personal ability or tolerance.'],['明日は早く来[られます]か。','Can you come early tomorrow?','Circumstantial possibility.'],['ここから海が見[られます]。','You can see the sea from here.','An available view.']]),
p('n4-070','Report information or identify a typical quality.','Plain clause + らしい; noun + らしい.','Neutral','Reported inference and typicality are distinct uses.','Do not insert だ immediately after a noun before らしい.',[
 ['来週、新しい店が開く[らしい]。','Apparently a new shop will open next week.','Information heard indirectly.'],['今日は春[らしい]天気です。','Today’s weather is typical of spring.','A characteristic quality.'],['田中さんは休み[らしい]です。','Apparently Ms. Tanaka is off today.','A reported situation.']]),
p('n4-071','Turn an adjective into a noun naming its degree or quality.','い-adjective stem / な-adjective stem + さ.','Neutral','This forms a quality noun; lexical naturalness still matters.','いい uses よさ rather than いさ.',[
 ['この山の高[さ]を知っていますか。','Do you know the height of this mountain?','A measurable property.'],['荷物の重[さ]を量ります。','I will weigh the luggage.','A degree noun.'],['この町の静か[さ]が好きです。','I like the quietness of this town.','A perceived quality.']]),
p('n4-072','Refer to a short time before the present.','さっき + past predicate.','Conversational','The interval is contextual and usually fairly recent.','Use a specific time when the listener needs an exact timestamp.',[
 ['[さっき]先生に会いました。','I saw the teacher a little while ago.','A recent encounter.'],['鍵は[さっき]ここに置いた。','I put the key here just now.','A recent action.'],['[さっき]まで雨が降っていました。','It was raining until a little while ago.','A recently ended situation.']]),
p('n4-073','Describe being made to perform an action.','Causative passive: ichidan stem + させられる; godan a-stem + せられる, often contracted to a-stem + される; する → させられる; 来る → 来させられる.','Neutral','Often suggests lack of choice; contractions depend on verb class.','The person forced to act is the subject of the causative passive.',[
 ['子供のころ、毎日走ら[されました]。','As a child, I was made to run every day.','A contracted godan form.'],['昨日は長い説明を聞か[されました]。','Yesterday I was made to listen to a long explanation.','An unwanted requirement.'],['苦手な野菜を食べ[させられた]。','I was made to eat vegetables I disliked.','An ichidan causative passive.']]),
p('n4-074','Describe causing or allowing someone to perform an action.','Ichidan stem + させる; godan a-stem + せる; する → させる; 来る → 来させる.','Neutral','Context determines whether it means make or let.','Causative participants and particles depend on the base verb’s transitivity.',[
 ['先生は学生に作文を書か[せました]。','The teacher had the students write an essay.','Assign an action.'],['母は子供を公園で遊ば[せた]。','The mother let the child play in the park.','Allow an activity.'],['その知らせは皆を安心[させた]。','The news reassured everyone.','Cause a state.']]),
p('n4-075','Ask permission to perform an action yourself.','Causative て-form + ください.','Polite request','The listener is asked to allow the speaker to act.','It differs from asking the listener to perform the base action.',[
 ['今日は早く帰ら[せてください]。','Please let me go home early today.','Request permission.'],['この本を読ま[せてください]。','Please let me read this book.','Ask to use something.'],['もう一度説明[させてください]。','Please allow me to explain once more.','Ask for a speaking opportunity.']]),
p('n4-076','Acknowledge a result as fitting someone’s reputation.','さすが + expected evaluation; さすがに + reaction to a limit.','Neutral','It often praises deserved ability, but the adverbial form has broader contextual uses.','It does not simply translate every occurrence of as expected.',[
 ['[さすが]先生、説明が分かりやすいです。','Just as you would expect from a teacher, your explanation is clear.','Praise established expertise.'],['[さすが]に三時間歩くと疲れます。','After walking for three hours, even I get tired.','A limit has been reached.'],['[さすが]プロですね。','You really are a professional.','Acknowledge skilled work.']]),
p('n4-077','List supporting reasons or linked qualities.','Plain or polite clause + し; repeat for additional reasons.','Neutral','Often implies other supporting reasons beyond those named.','Noun predicates need だし or ですし.',[
 ['この店は安い[し]、駅にも近いです。','This shop is inexpensive and also close to the station.','Supporting advantages.'],['疲れた[し]、今日は帰ろう。','I am tired, among other things, so let us go home today.','A reason for a decision.'],['彼は親切だ[し]、仕事も丁寧です。','He is kind and also careful in his work.','A な-adjective predicate.']]),
p('n4-078','Refer to a degree associated with the context.','そんなに + degree expression; often negative or a question.','Conversational','The comparison is to something already mentioned or observed.','It means that much, rather than automatically meaning very.',[
 ['[そんなに]急がなくてもいいです。','You do not have to hurry that much.','Refer to observed urgency.'],['この店は[そんなに]高くありません。','This shop is not that expensive.','Downplay an expected degree.'],['どうして[そんなに]驚いたのですか。','Why were you so surprised?','Ask about a visible reaction.']]),
p('n4-079','Continue despite a previously stated obstacle.','Sentence. それでも + sentence.','Neutral','The preceding situation remains true while the next action or outcome contrasts with it.','It differs from それなら, which accepts a premise for a next step.',[
 ['雨が強くなった。[それでも]、試合は続いた。','The rain grew heavier. Even so, the game continued.','Persist despite conditions.'],['何度も失敗した。[それでも]、あきらめなかった。','I failed many times. Even so, I did not give up.','Persistence.'],['高いと分かっていた。[それでも]、買いたかった。','I knew it was expensive. Even so, I wanted to buy it.','A desire survives an objection.']]),
p('n4-080','Add another supporting fact.','Sentence. それに + sentence.','Neutral','Often reinforces the same evaluation or argument.','Use a contrasting connector when the new point opposes the first.',[
 ['この部屋は広い。[それに]、駅にも近い。','This room is spacious. Besides, it is near the station.','Add an advantage.'],['今日は寒い。[それに]、風も強い。','It is cold today. Also, the wind is strong.','Add another condition.'],['彼は経験がある。[それに]、英語も話せる。','He has experience. In addition, he speaks English.','Supporting qualifications.']]),
p('n4-081','Pass on information you have heard or read.','Plain clause + そうだ; noun / な-adjective + だそうだ.','Neutral','Identify or imply an information source; this is not visual appearance そうだ.','Keep plain だ after noun predicates for reported information.',[
 ['天気予報によると、明日は雨が降る[そうです]。','According to the forecast, it will rain tomorrow.','Reported information.'],['田中さんは元気[だそうです]。','I hear Ms. Tanaka is well.','A reported な-adjective predicate.'],['この店は百年前からある[そうだ]。','I hear this shop has been here for a hundred years.','Information learned from a source.']]),
p('n4-082','Describe an impression from visible signs or an imminent event.','ます-stem / adjective stem + そうだ; いい → よさそう.','Neutral','Appearance そう does not attach to plain verbs in the same way as hearsay そう.','Compare 降りそう, looks about to rain, with 降るそう, I hear it will rain.',[
 ['空が暗くて、雨が降り[そうです]。','The sky is dark, and it looks about to rain.','Visible signs.'],['このケーキはおいし[そうです]。','This cake looks delicious.','An appearance-based judgment.'],['この椅子は丈夫[そうです]。','This chair looks sturdy.','A visible impression.']]),
p('n4-083','Use an appearance impression to modify a noun or action.','Appearance stem + そうな + noun; + そうに + verb.','Neutral','These derive from appearance そうだ, not the hearsay construction.','Use な before a noun and に before a predicate.',[
 ['子供は楽し[そうに]遊んでいます。','The children are playing happily.','Observed manner.'],['おいし[そうな]パンを買いました。','I bought some delicious-looking bread.','Modify a noun.'],['彼は眠[そうに]目をこすった。','He rubbed his eyes sleepily.','An apparent state during an action.']]),
p('n4-084','Describe an action as recently completed from the speaker’s perspective.','た-form + ばかり.','Neutral','The elapsed time can be longer than a literal moment if it feels recent in context.','Do not impose the immediate-instant meaning of たところ on every たばかり.',[
 ['日本に来た[ばかり]です。','I have only recently come to Japan.','A recent arrival.'],['昼ご飯を食べた[ばかり]なので、お腹がすいていません。','I have just eaten lunch, so I am not hungry.','A recent action affects now.'],['先月買った[ばかり]の靴です。','These are shoes I only bought last month.','Recent on a relevant timescale.']]),
p('n4-085','Locate the present moment immediately after an action ends.','た-form + ところ.','Neutral','Focuses on the action’s just-completed stage.','For broader subjective recency, たばかり may be more appropriate.',[
 ['今、駅に着いた[ところ]です。','I have just arrived at the station.','Immediate completion.'],['ちょうど仕事が終わった[ところ]です。','I have just finished work.','The current stage.'],['お湯を沸かした[ところ]なので、すぐ飲めます。','I have just boiled the water, so we can have a drink right away.','A freshly completed action.']]),
p('n4-086','Distinguish an affected object from a change in the thing itself.','Transitive: object + を + verb; intransitive: subject + が + verb.','Neutral','Many verb pairs are lexical and must be learned individually.','Do not create a transitive verb by freely changing a vowel.',[
 ['私が窓を[開けました]。','I opened the window.','A transitive action affects an object.'],['風で窓が[開きました]。','The window opened in the wind.','An intransitive change.'],['電気を[消した]ら、部屋が暗くなった。','When I turned off the light, the room became dark.','A deliberate transitive action.']]),
p('n4-087','Describe another person’s observable wish to act.','ます-stem + たがる / たがっている.','Neutral','Reports behavior or signs of wanting rather than directly quoting the person’s inner wish.','Use たい for an ordinary statement of your own desire.',[
 ['弟は外で遊び[たがっています]。','My younger brother wants to play outside.','An observed desire.'],['子供たちは新しいゲームをし[たがっている]。','The children want to play the new game.','A visible group preference.'],['犬は家に入り[たがっている]。','The dog wants to come inside.','Interpret behavior.']]),
p('n4-088','Make a later event depend on a completed condition.','た-form + ら; copula だったら.','Neutral','May express a hypothetical condition or a time when something happens.','The past-looking form does not necessarily place the condition in past time.',[
 ['雨が降っ[たら]、家にいます。','If it rains, I will stay home.','A hypothetical condition.'],['駅に着い[たら]、電話してください。','Please call when you reach the station.','A future completed condition.'],['家に帰っ[たら]、誰もいなかった。','When I got home, no one was there.','A discovery after an event.']]),
p('n4-089','Offer an action as a possible solution.','たら + どう（ですか）.','Neutral / polite','Advice can sound critical depending on the relationship and intonation.','The past-form condition suggests a future action here.',[
 ['先生に聞い[たらどうですか]。','Why not ask the teacher?','Suggest a source of help.'],['少し休ん[だらどう]。','Why do you not take a short break?','A casual suggestion.'],['別の道を通っ[たらどうですか]。','How about taking another road?','An alternative solution.']]),
p('n4-090','Ask which action would be advisable.','Question word + verb たら + いいですか.','Polite','The speaker asks for guidance about a choice or procedure.','Keep the question word that identifies the missing information.',[
 ['どこで切符を買っ[たらいいですか]。','Where should I buy a ticket?','Ask for a place.'],['何を持って行っ[たらいいですか]。','What should I bring?','Ask for an item.',{"行っ":"いっ"}],['誰に連絡し[たらいいですか]。','Who should I contact?','Ask for a person.']]),
p('n4-091','Connect descriptions or actions with a て-form.','Verb て-form; い-adjective ～くて; noun / な-adjective + で.','Neutral','The relationship can be sequence, accompanying manner, or a contextual cause.','Choose the correct connector for the word class.',[
 ['手を洗っ[て]、料理を始めました。','I washed my hands and began cooking.','Sequence.'],['この部屋は広く[て]、明るいです。','This room is spacious and bright.','Linked い-adjective descriptions.'],['駅は静か[で]、きれいです。','The station is quiet and clean.','Linked な-adjective descriptions.']]),
p('n4-092','Describe doing a helpful action for someone else.','て-form + あげる.','Neutral','Explicitly presenting your action as a favor can sound patronizing in some relationships.','The giver of the action is the subject, not the recipient.',[
 ['妹に本を読ん[であげた]。','I read a book to my younger sister.','A helpful action.'],['友達の荷物を持っ[てあげました]。','I carried my friend’s bags for them.','Help someone with a task.'],['弟に漢字を教え[てあげた]。','I taught my younger brother some kanji.','A teaching favor.']]),
p('n4-093','Express a wish that someone perform an action.','Person + に + て-form + ほしい.','Neutral','Often states the speaker’s desire; a direct wish about another person can impose on them.','For wanting an object, use noun + がほしい.',[
 ['友達に手伝っ[てほしい]です。','I would like my friend to help.','A desired action by someone else.'],['皆にこの本を読ん[でほしい]。','I want everyone to read this book.','A recommendation framed as a wish.'],['もう少し静かにし[てほしい]です。','I would like it to be a little quieter.','A request-like desire.']]),
p('n4-094','Describe movement away or a development continuing into the future.','て-form + いく.','Neutral','The viewpoint establishes what counts as away or onward.','Do not interpret every ていく as physical departure.',[
 ['鳥が遠くへ飛ん[でいった]。','The bird flew away into the distance.','Movement away.'],['これからも勉強を続け[ていきます]。','I will continue studying from now on.','A future continuation.'],['秋になると、だんだん寒くなっ[ていく]。','As autumn arrives, it gradually gets colder.','A developing change.']]),
p('n4-095','Describe an action or state continuing at a past reference time.','て-form + いた.','Neutral','Depending on the verb, it may describe past progress, a habit, or a resulting state.','It does not always mean a single action was in progress.',[
 ['電話が来たとき、本を読ん[でいた]。','I was reading when the phone rang.','A past action in progress.'],['子供のころ、海の近くに住ん[でいた]。','I lived near the sea as a child.','A past continuing situation.'],['着いたとき、店はもう閉まっ[ていた]。','When I arrived, the shop was already closed.','A past result state.']]),
p('n4-096','Ask for a favor with a deferential potential question.','て-form + いただけませんか.','Polite / deferential','The speaker asks whether they could receive the benefit of the listener’s action.','The listener performs the action; it is not permission for the speaker to act.',[
 ['もう一度説明し[ていただけませんか]。','Could you please explain it once more?','A request for clarification.'],['この書類を確認し[ていただけませんか]。','Could you please check this document?','A work request.'],['少し待っ[ていただけませんか]。','Could you please wait a moment?','A deferential request.']]),
p('n4-097','Describe someone doing a helpful action toward your side.','て-form + くれる.','Neutral','The benefit is viewed from the speaker or someone identified with the speaker.','The helper is the grammatical subject.',[
 ['友達が道を教え[てくれた]。','My friend showed me the way.','A favor received.'],['姉が夕食を作っ[てくれました]。','My older sister made dinner for me.','An action benefits the speaker.'],['先生が弟を励まし[てくれた]。','The teacher encouraged my younger brother.','Benefit to someone on the speaker’s side.']]),
p('n4-098','Describe movement toward now or a change developing up to now.','て-form + くる.','Neutral','It may express physical approach, a round trip, or a developing state.','Interpret the viewpoint from the surrounding sentence.',[
 ['犬がこちらへ走っ[てきた]。','The dog ran toward us.','Physical approach.'],['少し寒くなっ[てきました]。','It has started to get a little colder.','A change becoming noticeable now.'],['飲み物を買っ[てきます]。','I will go and buy drinks and come back.','A round trip.']]),
p('n4-099','Try an action to find out what happens.','て-form + みる.','Neutral','It describes an actual trial; ようとする focuses on an attempt or intention.','The auxiliary みる is ordinarily written in kana.',[
 ['この靴を履い[てみます]。','I will try these shoes on.','Test suitability.'],['別の方法でやっ[てみよう]。','Let us try doing it another way.','An experiment.'],['日本語で注文し[てみました]。','I tried ordering in Japanese.','Try out a skill.']]),
p('n4-100','Present yourself as receiving someone’s helpful action.','Recipient + は / が + helper + に + て-form + もらう.','Neutral','The recipient is the subject; くれる instead makes the helper the subject.','に marks the helper in the ordinary pattern.',[
 ['友達に荷物を持っ[てもらいました]。','I had my friend carry my bags for me.','A favor received.'],['先生に作文を直し[てもらった]。','I had the teacher correct my essay.','Help with a task.'],['姉に写真を撮っ[てもらいました]。','I had my older sister take a photo for me.','Ask someone to help.']]),
p('n4-101','Prepare for a later need or leave a state unchanged.','て-form + おく.','Neutral','Often implies acting in advance; context can instead mean keeping something as it is.','It does not mean every action literally involves putting an object somewhere.',[
 ['旅行の前に切符を買っ[ておきます]。','I will buy the tickets before the trip.','Preparation.'],['明日の資料を読ん[でおいた]。','I read tomorrow’s documents in advance.','An advance task.'],['窓は開け[ておいて]ください。','Please leave the window open.','Maintain a state.']]),
p('n4-102','Present an action as completed or regrettable.','て-form + しまう; spoken てしまう → ちゃう, でしまう → じゃう.','Neutral; contractions casual.','Regret depends on context; completion can be neutral or intentional.','Do not assume しまう always means an accident.',[
 ['財布を忘れ[てしまいました]。','I unfortunately left my wallet behind.','Regret.'],['今日中に全部読ん[でしまおう]。','Let us finish reading all of it today.','Intentional completion.'],['最後のパンを食べ[ちゃった]。','I ate the last piece of bread.','A conversational contraction.']]),
p('n4-103','Apologize for an action or resulting situation.','て-form + すみません; past apology すみませんでした.','Polite','A specific apology normally names what caused inconvenience.','For not doing something, なくてすみません is often needed.',[
 ['遅れ[てすみません]。','I am sorry I am late.','A present apology.'],['急に電話し[てすみません]。','I am sorry to call so suddenly.','An interruption.'],['長く待たせ[てすみませんでした]。','I am sorry I kept you waiting so long.','An apology for a past inconvenience.']]),
p('n4-104','Describe doing something for someone lower in a traditional hierarchy.','て-form + やる.','Plain; potentially rough','Common with animals or plants; toward people it can sound condescending or assertive.','Use a relationship-appropriate benefactive rather than assuming やる is neutral.',[
 ['鉢の花を日なたに移し[てやった]。','I moved the potted flowers into the sunlight.','Care for plants in a rough plain style.'],['犬を公園に連れて行っ[てやった]。','I took the dog to the park.','A favor for an animal.',{"行っ":"いっ"}],['弟の宿題を見[てやった]。','I helped my younger brother with his homework.','A familiar, potentially condescending stance.']]),
p('n4-105','Express relief or satisfaction about what happened.','て-form + よかった; negative なくてよかった.','Neutral','The speaker evaluates an actual outcome; this is not ordinary advice about a future action.','Do not confuse てよかった with たほうがいい.',[
 ['早く出発し[てよかった]。','I am glad we left early.','A fortunate decision.'],['皆に会え[てよかった]です。','I am glad I could see everyone.','A welcome outcome.'],['雨に降られ[なくてよかった]。','I am glad we did not get caught in the rain.','Relief about non-occurrence.']]),
p('n4-106','Identify an action as currently in progress.','て-form + いるところ.','Neutral','Focuses on the stage of the action at the reference time.','ところ here is not a physical place.',[
 ['今、昼ご飯を作っ[ているところ]です。','I am in the middle of making lunch.','Current activity.'],['資料を確認し[ているところ]です。','I am currently checking the documents.','Report a work stage.'],['ちょうど帰る準備をし[ているところ]でした。','I was just getting ready to go home.','A past reference point.']]),
p('n4-107','Say a result holds even if a condition occurs.','て-form + も; adjective ～くても; noun / な-adjective + でも.','Neutral','Unlike ordinary conditional forms, it maintains the result despite the condition.','Use the correct connector for the word class.',[
 ['雨が降っ[ても]、試合をします。','We will play even if it rains.','A plan survives a condition.'],['高く[ても]、必要なら買います。','Even if it is expensive, I will buy it if necessary.','A concessive property.'],['日曜日[でも]、この店は開いています。','This shop is open even on Sundays.','A noun-based concession.',{"開い":"あい"}]]),
p('n4-108','Link a condition with an expected or automatic consequence.','Dictionary-form / ない-form verb + と.','Neutral','Often suits habitual or mechanical results; ordinary commands and invitations need another construction.','Do not use this conditional for every personal request.',[
 ['春になる[と]、桜が咲きます。','When spring comes, the cherry blossoms bloom.','A regular natural result.'],['このボタンを押す[と]、ドアが開きます。','If you press this button, the door opens.','A mechanical consequence.'],['右に曲がる[と]、駅があります。','When you turn right, there is a station.','A route leads to a discovery.']]),
p('n4-109','Say that a description is a reasonable characterization.','Plain clause + と言ってもいい.','Neutral','Allows an approximate or defensible description rather than asserting literal identity.','The phrase concerns how something may be described, not physical permission to speak.',[
 ['この仕事は成功した[と言ってもいい]。','It would be fair to say this work was a success.','A defensible evaluation.'],['彼はこの町の代表[と言ってもいい]。','You could call him a representative of this town.','An approximate role.'],['ここは第二の故郷[と言ってもいい]です。','I could call this my second hometown.','A personal characterization.']]),
p('n4-110','Attach a name or label to something.','Name / quoted expression + という + noun.','Neutral','The following noun names the category of the labeled thing.','It need not describe someone literally saying the name aloud.',[
 ['田中[という]人から電話がありました。','There was a call from someone named Tanaka.','Introduce an unfamiliar name.'],['「春の風」[という]本を読んでいます。','I am reading a book called Spring Wind.','Name a work.'],['桜町[という]町に住んでいます。','I live in a town called Sakuramachi.','Name a place.']]),
p('n4-111','Turn the content of a statement into a named fact or idea.','Plain clause + ということ.','Neutral','The surrounding predicate determines whether the idea is learned, understood, or discussed.','This nominalization alone does not always report hearsay.',[
 ['明日が休みだ[ということ]を忘れていた。','I had forgotten that tomorrow is a day off.','A fact as object.'],['彼が来ない[ということ]は知っています。','I know that he is not coming.','Known information.'],['毎日続ける[ということ]は簡単ではない。','Continuing every day is not easy.','An idea as topic.']]),
p('n4-112','Report a description as something generally said.','Plain clause + と言われている.','Neutral / written','It attributes a claim to general reporting; it does not establish its truth.','Distinguish a general report from a specific person’s direct quotation.',[
 ['この町は静かだ[と言われています]。','This town is said to be quiet.','A general description.'],['この花は春に咲く[と言われている]。','This flower is said to bloom in spring.','Reported knowledge.'],['その橋は百年前にできた[と言われています]。','That bridge is said to have been built a hundred years ago.','A historical report.']]),
p('n4-113','State the content of information heard from a source.','Plain clause + と聞いた / と聞きました.','Neutral','The speaker reports having heard the information.','Use plain だ in a quoted noun predicate when needed.',[
 ['田中さんから、会議は中止だ[と聞きました]。','I heard from Ms. Tanaka that the meeting was canceled.','A named source.'],['あの店は安い[と聞いた]。','I heard that shop is inexpensive.','A reported evaluation.'],['来月引っ越す[と聞きました]。','I heard you are moving next month.','Information about a future event.']]),
p('n4-114','Present the content of a thought or opinion.','Plain clause + と思う.','Neutral','Direct present 思う normally reports the speaker’s thought; others’ ongoing thoughts often use 思っている.','Use plain rather than polite form inside the ordinary quoted clause.',[
 ['明日は晴れる[と思います]。','I think it will be sunny tomorrow.','A prediction.'],['これは良い方法だ[と思う]。','I think this is a good method.','An opinion with noun predicate だ.'],['彼は来ない[と思います]。','I do not think he will come.','A negative proposition.']]),
p('n4-115','List conversational examples of items or activities.','Noun / plain clause + とか; repeat for further examples.','Conversational','The list suggests examples rather than an exhaustive inventory.','Reported hearsay とか at a clause ending is a related but different use.',[
 ['パン[とか]果物[とか]を食べます。','I eat things like bread and fruit.','Examples of foods.'],['週末は映画を見る[とか]、散歩する[とか]しています。','On weekends I do things like watching films or walking.','Examples of activities.'],['青[とか]緑[とか]が好きです。','I like colors such as blue and green.','Representative preferences.']]),
p('n4-116','Identify an action as about to begin.','Dictionary-form verb + ところ.','Neutral','This form locates the action immediately before its start; ているところ and たところ mark other stages.','The nonpast verb does not mean the action is already underway.',[
 ['今から家を出る[ところ]です。','I am just about to leave home.','An imminent action.'],['これから昼ご飯を食べる[ところ]です。','I am just about to eat lunch.','A current stage.'],['電話しようと思っていたら、彼から電話が来た。ちょうどかける[ところ]だった。','He called while I was thinking of calling him. I was just about to make the call.','A past imminent action.']]),
p('n4-117','Describe keeping an action going.','ます-stem + 続ける.','Neutral','The verb must support an interpretable continuing or repeated activity.','Attach 続ける to the stem rather than a full dictionary-form verb.',[
 ['雨が降り[続けています]。','The rain keeps falling.','A continuing process.'],['毎日、練習し[続けます]。','I will keep practicing every day.','Repeated effort.'],['彼は三時間も話し[続けた]。','He kept talking for three hours.','An extended action.']]),
p('n4-118','Quote speech or introduce a topic conversationally.','Quoted clause / noun + って.','Casual','It can replace quotative と or introduce a topic; context distinguishes the functions.','It is generally unsuitable as a replacement in formal writing.',[
 ['明日は休みだ[って]聞いた。','I heard that tomorrow is a day off.','Casual quotation.'],['田中さん[って]、どんな人ですか。','What is Tanaka like?','Introduce a topic.'],['母が早く帰って[って]言っていた。','My mother said to come home early.','Quote a request.']]),
p('n4-119','Describe an action from the perspective of its receiver.','Godan a-stem + れる; ichidan stem + られる; する → される; 来る → 来られる.','Neutral','Japanese also uses indirect passives for events affecting someone.','Mark the agent appropriately, often with に; られる can have other meanings.',[
 ['私は先生に褒め[られました]。','I was praised by the teacher.','A direct passive.'],['この本は多くの人に読ま[れています]。','This book is read by many people.','An object as passive subject.'],['旅行中、雨に降ら[れた]。','I got caught in the rain during the trip.','An affected-person passive.']]),
p('n4-120','Contrast two topics across opposing statements.','A + は + predicate + が; B + は + contrasting predicate.','Neutral','The contrasted topics and qualities should be understandable from context.','The connective が and topic は play different roles.',[
 ['兄[は]背が高い[が]、弟[は]低い。','My older brother is tall, but my younger brother is short.','Contrast people.'],['夏[は]暑い[が]、冬[は]寒い。','Summer is hot, but winter is cold.','Contrast seasons.'],['お茶[は]飲む[が]、コーヒー[は]飲まない。','I drink tea, but I do not drink coffee.','Contrast choices.']]),
p('n4-121','Describe an action as easy to perform.','ます-stem + やすい.','Neutral','It conjugates as an い-adjective; some uses describe a tendency to happen.','Use 読みやすい, not 読むやすい.',[
 ['この本は読み[やすい]です。','This book is easy to read.','An accessible object.'],['この靴は歩き[やすい]。','These shoes are easy to walk in.','A helpful design.'],['雨の日は道が滑り[やすい]。','The road is slippery on rainy days.','A tendency to happen.']]),
p('n4-122','Express relief that a long-awaited result finally occurred.','やっと + achieved result.','Neutral','Usually highlights effort, delay, or waiting.','It does not fit every neutral occurrence of finally in a chronological list.',[
 ['[やっと]宿題が終わった。','I finally finished my homework.','Relief after effort.'],['[やっと]バスが来ました。','The bus has finally come.','A long wait.'],['何度も練習して、[やっと]泳げるようになった。','After practicing many times, I finally learned to swim.','An achievement.']]),
p('n4-123','Mark the reference point for a comparison.','Reference noun / clause + より.','Neutral','The item before より is the benchmark, not automatically the greater item.','Understand the direction from the full sentence.',[
 ['昨日[より]今日は暖かいです。','Today is warmer than yesterday.','A time benchmark.'],['歩く[より]自転車のほうが速い。','Cycling is faster than walking.','Compare actions.'],['この道は思った[より]長かった。','This road was longer than I expected.','An expectation as benchmark.']]),
p('n4-124','Describe an action as scheduled or planned.','Dictionary-form verb + 予定だ; noun + の予定だ.','Neutral','Often suggests an arrangement or schedule rather than only a personal wish.','Use a noun with の before 予定.',[
 ['来週、出張する[予定です]。','I am scheduled to go on a business trip next week.','A work plan.'],['会議は三時に始まる[予定です]。','The meeting is scheduled to start at three.','A timetable.'],['明日は休みの[予定です]。','I am scheduled to be off tomorrow.','A noun-based arrangement.']]),
p('n4-125','Express a resemblance or inference based on indications.','Plain verb / い-adjective + ようだ; noun + のようだ; な-adjective + なようだ.','Neutral','The evidence may be indirect or sensory; formation differs by word class.','Use noun + のようだ rather than noun + ようだ directly.',[
 ['あの雲は魚の[ようだ]。','That cloud looks like a fish.','A resemblance.'],['隣の部屋で会議をしている[ようです]。','It seems they are having a meeting next door.','An inference from signs.'],['この問題は簡単ではない[ようだ]。','This problem does not seem easy.','An assessment.']]),
p('n4-126','Use a resemblance to describe an action or noun.','Noun + のように / のような; plain phrase + ように / ような.','Neutral','ように modifies a predicate; ような modifies a noun.','Do not interchange な and に without changing the following structure.',[
 ['鳥の[ように]空を飛びたい。','I want to fly through the sky like a bird.','Modify an action.'],['雪の[ような]白い花です。','It is a white flower like snow.','Modify a noun.'],['先生が言った[ように]書いてください。','Please write it as the teacher said.','Follow a described manner.']]),
p('n4-127','Describe a change in ability or habitual behavior.','Potential / nonpast verb + ようになる; negative verb + ようになる.','Neutral','It focuses on a transition rather than a single successful event.','Use potential form when the intended change is ability.',[
 ['漢字が読める[ようになりました]。','I have become able to read kanji.','A new ability.'],['毎朝、散歩する[ようになった]。','I started taking a walk every morning.','A new habit.'],['最近はあまりテレビを見ない[ようになった]。','Recently I have come to watch little television.','A changed habit.']]),
p('n4-128','Make a deliberate effort or establish a personal practice.','Dictionary-form / ない-form verb + ようにする.','Neutral','Often presents an ongoing effort; a single firm decision can use ことにする.','The expression does not promise perfect success on every occasion.',[
 ['毎日、野菜を食べる[ようにしています]。','I make a point of eating vegetables every day.','An ongoing practice.'],['遅れない[ようにしてください]。','Please make sure you are not late.','An effort requested.'],['寝る前に画面を見ない[ようにする]。','I will try not to look at screens before bed.','A deliberate habit.']]),
p('n4-129','Express an intention using a quoted volitional form.','Volitional form + と思う / と思っている.','Neutral','思っている often presents an intention held over time.','The action is intended, rather than necessarily already arranged.',[
 ['週末は図書館へ行こ[うと思います]。','I think I will go to the library this weekend.','A present intention.'],['来年、日本語の試験を受け[ようと思っています]。','I am thinking of taking a Japanese test next year.','A continuing plan.'],['今日は早く帰ろ[うと思う]。','I think I will go home early today.','A personal decision.']]),
p('n4-130','Express a strong wish or warmly encourage an action.','ぜひ + wish, invitation, or request.','Neutral / polite','Common with desirable actions; it does not simply emphasize every factual statement.','Use it with a context of willingness or encouragement.',[
 ['[ぜひ]日本へ行ってみたいです。','I would really like to visit Japan.','A strong wish.',{"行っ":"いっ"}],['近くに来たら、[ぜひ]寄ってください。','If you are nearby, please do stop by.','A warm invitation.'],['この本を[ぜひ]読んでください。','Please do read this book.','An enthusiastic recommendation.']]),
p('n4-131','Emphasize a complete absence or negation.','全然 + negative predicate.','Neutral','Positive colloquial uses exist, but this pattern teaches the standard negative construction.','The predicate supplies the negative meaning.',[
 ['この問題は[全然]分から[ない]。','I do not understand this problem at all.','Complete lack of understanding.'],['今日は[全然]寒く[ない]です。','It is not cold at all today.','Strongly negate a property.'],['昨日は[全然]眠れ[なかった]。','I could not sleep at all yesterday.','A complete failure to act.']]),
p('n4-132','Describe an action as burdensome or difficult to carry out.','ます-stem + づらい.','Neutral','Often highlights discomfort or personal difficulty; it can overlap with にくい.','づらい follows a verb stem, not the dictionary form.',[
 ['この話は本人には言い[づらい]。','This is hard to say to the person concerned.','An emotional difficulty.'],['足が痛くて歩き[づらい]。','My foot hurts, making it difficult to walk.','Physical discomfort.'],['小さい文字は読み[づらい]です。','Small print is difficult to read.','A burdensome task.']]),
];
